import numpy as np
import limited_client as robot
for c in (0,1,2,3):
 o=robot.observe(camera=c)
 print('\nCAM',c,'robot',o['robot'])
 if c in (0,1,2):
  im=o['rgb'].astype(float); d=o['depth_m']; K=o['intrinsic']; T=o['camera_to_world']; inv=np.linalg.inv(K)
  masks={
   'green':(im[:,:,1]>im[:,:,0]*1.12)&(im[:,:,1]>im[:,:,2]*1.12)&(im[:,:,1]>50),
   'blue':(im[:,:,2]>im[:,:,0]*1.12)&(im[:,:,2]>im[:,:,1]*1.03)&(im[:,:,2]>50)}
  for name,m in masks.items():
   yy,xx=np.where(m)
   if len(xx):
    print(name,'pixels',len(xx),'bbox',(int(xx.min()),int(xx.max()),int(yy.min()),int(yy.max())))
    ids=np.linspace(0,len(xx)-1,min(12,len(xx)),dtype=int); ws=[]
    for j in ids:
     u,v=int(xx[j]),int(yy[j]); z=float(d[v,u])
     if z>0 and z<3:
      w=T@np.r_[inv@np.array([u,v,1.])*z,1.]; ws.append(w[:3])
    if ws: print(name,'world median',np.round(np.median(ws,axis=0),4))
print('\nSTATUS',robot.status())
